// Re-hydrate _schools from the separate school-map.json onto account records
function hydrateSchools(accounts) {
  accounts.forEach(d => {
    const key = (d.name || '') + '|' + (d.state || '');
    if (schoolMap[key]) d._schools = schoolMap[key];
  });
}

// ============ ADA STATES ============
const ADA_STATES = new Set(['CA', 'TX', 'ID', 'KY', 'MS', 'MO']);

function isAdaAccount(d) {
  return !!d.ada_adm || ADA_STATES.has(d.state);
}

// ============ LOCAL STORAGE PERSISTENCE ============
// Keys used to store merged data so it survives page refreshes.
const LS_ACCOUNTS_KEY = 'edia_account_data';
const LS_CUSTOMERS_KEY = 'edia_customer_data';
const LS_DATA_SAVED_KEY = 'edia_data_saved_at';
const LS_CONFLICTS_KEY = 'edia_conflicts';
const LS_OPPS_KEY = 'edia_opp_data';

/** Save account and/or customer data to localStorage. */
function saveDataToLocalStorage(accounts, customers) {
  try {
    if (accounts) localStorage.setItem(LS_ACCOUNTS_KEY, JSON.stringify(accounts));
    if (customers) localStorage.setItem(LS_CUSTOMERS_KEY, JSON.stringify(customers));
    localStorage.setItem(LS_DATA_SAVED_KEY, new Date().toISOString());
    console.log('[Persist] Data saved to localStorage');
  } catch (e) {
    console.warn('[Persist] Could not save to localStorage:', e.message);
    alert('Warning: Could not save data to browser storage. Your browser storage may be full. Recent changes may be lost on refresh.');
  }
}

/** Load data from localStorage, returning null if nothing saved. */
function loadDataFromLocalStorage() {
  try {
    const acct = localStorage.getItem(LS_ACCOUNTS_KEY);
    const cust = localStorage.getItem(LS_CUSTOMERS_KEY);
    if (acct || cust) {
      console.log('[Persist] Loading data from localStorage');
      return {
        accounts: acct ? JSON.parse(acct) : null,
        customers: cust ? JSON.parse(cust) : null,
        savedAt: localStorage.getItem(LS_DATA_SAVED_KEY),
      };
    }
  } catch (e) {
    console.warn('[Persist] Could not load from localStorage:', e.message);
  }
  return null;
}

/** Clear persisted data so the app falls back to bundled JSON. */
function clearPersistedData() {
  localStorage.removeItem(LS_ACCOUNTS_KEY);
  localStorage.removeItem(LS_CUSTOMERS_KEY);
  localStorage.removeItem(LS_OPPS_KEY);
  localStorage.removeItem(LS_DATA_SAVED_KEY);
  console.log('[Persist] Cleared saved data — will use bundled JSON on next load');
}

export function saveOppsToLocalStorage(opps) {
  try {
    localStorage.setItem(LS_OPPS_KEY, JSON.stringify(opps));
  } catch (e) {
    console.warn('[Persist] Could not save opps to localStorage:', e.message);
  }
}

/** Load conflict records from localStorage. */
function loadConflicts() {
  try {
    const data = localStorage.getItem(LS_CONFLICTS_KEY);
    return data ? JSON.parse(data) : [];
  } catch (e) { return []; }
}

/** Save conflict records to localStorage. */
export function saveConflicts(conflicts) {
  try {
    localStorage.setItem(LS_CONFLICTS_KEY, JSON.stringify(conflicts));
  } catch (e) {
    console.warn('[Conflicts] Could not save:', e.message);
  }
}

// Active conflicts (loaded on startup, updated during merges)
S.CONFLICTS = loadConflicts();

// ============ OPP HELPERS (must be above DATA INITIALIZATION for migration) ============
// These are needed at module-load time when migrating localStorage data.
export const OPP_ENTRY_FIELDS = new Set([
  'opp_stage', 'opp_forecast', 'opp_areas', 'opp_acv', 'opp_probability',
  'opp_contact', 'opp_contact_title', 'opp_next_step', 'opp_last_activity',
  'opp_sdr', 'opp_champion', 'opp_economic_buyer', 'opp_competition'
]);

export const OPP_WRAPPER_FIELDS = new Set([
  'opp_owner', 'opportunity_name', 'intro_meeting_date',
  'created_date', 'last_modified', 'age',
  'metric_improvement_goal', 'decision_criteria', 'decision_process',
  'paper_process', 'implication_of_pain'
]);

export function buildOppEntry(oppFields) {
  return {
    area: normalizeOppArea(oppFields.opp_areas || ''),
    stage: oppFields.opp_stage || '',
    forecast: oppFields.opp_forecast || '',
    acv: oppFields.opp_acv || '',
    probability: oppFields.opp_probability || '',
    contact: oppFields.opp_contact || '',
    contact_title: oppFields.opp_contact_title || '',
    next_step: oppFields.opp_next_step || '',
    last_activity: oppFields.opp_last_activity || '',
    sdr: oppFields.opp_sdr || '',
    champion: oppFields.opp_champion || '',
    economic_buyer: oppFields.opp_economic_buyer || '',
    competition: oppFields.opp_competition || '',
  };
}

export function migrateToOppsArray(record) {
  if (record.opps && record.opps.length > 0) return; // Already has opps entries
  if (!record.opp_stage && !record.opp_areas) return; // No flat opp fields to migrate
  const oppFields = {};
  OPP_ENTRY_FIELDS.forEach(f => {
    if (record[f]) oppFields[f] = record[f];
  });
  if (Object.keys(oppFields).length > 0) {
    record.opps = [buildOppEntry(oppFields)];
  }
}

// ============ DATA INITIALIZATION ============
// On startup, prefer localStorage data (from a previous merge) over the bundled JSON.
// This ensures that a CSV merge persists across page refreshes without redeploying.
const _persisted = loadDataFromLocalStorage();
S._dataSource = 'bundled';

// Mutable data arrays (can be replaced on refresh)
S.ACCOUNT_DATA = _persisted && _persisted.accounts ? [..._persisted.accounts] : [...accountData];
S.CUSTOMER_DATA = _persisted && _persisted.customers ? [..._persisted.customers] : [...customerData];
if (_persisted) {
  S._dataSource = 'localStorage';
  // Repair enrollment values corrupted by CSV comma formatting (e.g. "30,210" → 30).
  // Bundled accounts.json is the enrollment source of truth.
  const _bundledEnrollment = new Map();
  accountData.forEach(d => { if (d.enrollment) _bundledEnrollment.set(d.name, d.enrollment); });
  let _repaired = 0;
  S.ACCOUNT_DATA.forEach(d => {
    const bundled = _bundledEnrollment.get(d.name);
    if (bundled && (!d.enrollment || d.enrollment < bundled)) {
      d.enrollment = bundled;
      _repaired++;
    }
  });
  if (_repaired) console.log(`[Persist] Repaired enrollment for ${_repaired} account(s) from bundled data`);
  // Migrate flat opp fields into opps array for existing localStorage data
  let _migrated = 0;
  S.ACCOUNT_DATA.forEach(d => {
    // Migrate if no opps array, OR opps is empty but flat fields exist
    if ((!d.opps || d.opps.length === 0) && (d.opp_stage || d.opp_areas)) {
      migrateToOppsArray(d);
      _migrated++;
    }
  });
  if (_migrated) console.log(`[Persist] Migrated ${_migrated} account(s) from flat opp fields to opps array`);

  // Repair: ensure deriveOppSummary has run on all accounts with opps
  let _derivedRepairs = 0;
  S.ACCOUNT_DATA.forEach(d => {
    if (d.opps && d.opps.length > 0 && !d.opp_stage) {
      deriveOppSummary(d);
      _derivedRepairs++;
    }
  });
  if (_derivedRepairs) console.log(`[Persist] Repaired derived opp fields for ${_derivedRepairs} account(s)`);

  // Repair unmapped SFDC field names from earlier CSV merges.
  // Old code didn't map "Billing State/Province" → state, "Active ARR" → arr, etc.
  // Records saved to localStorage still have the raw normalized keys.
  const _sfdcFieldRepairs = {
    'billing_state_province': 'state',
    'billing_state': 'state',
    'shipping_state_province': 'state',
    'shipping_state': 'state',
    'billing_address_line_1': 'address',
    'billing_address': 'address',
    'shipping_address_line_1': 'address',
    'shipping_address': 'address',
    'billing_city': 'city',
    'shipping_city': 'city',
    'active_arr': 'arr',
    'total_active_arr': 'arr',
    'account_owner': 'ae',
    'customer_success_manager': 'csm',
    'account_name': 'name',
    'students_in_district': 'enrollment',
  };
  let _fieldRepairs = 0;
  const _repairRecords = (records) => {
    records.forEach(d => {
      Object.entries(_sfdcFieldRepairs).forEach(([raw, mapped]) => {
        if (d[raw] !== undefined && d[raw] !== '') {
          // Only set the mapped field if it's empty (don't overwrite existing values)
          if (!d[mapped]) {
            d[mapped] = d[raw];
            _fieldRepairs++;
          }
          delete d[raw];
        }
      });
    });
  };
  _repairRecords(S.ACCOUNT_DATA);
  _repairRecords(S.CUSTOMER_DATA);
  if (_fieldRepairs) {
    console.log(`[Persist] Repaired ${_fieldRepairs} unmapped SFDC field(s) in localStorage data`);
    // Save repaired data back to localStorage so this migration only runs once
    saveDataToLocalStorage(S.ACCOUNT_DATA, S.CUSTOMER_DATA);
  }
}

// ============ CROSS-LINK CUSTOMERS ↔ ACCOUNTS ============
// Sets is_customer / customer_name on accounts that match a customer record,
// and also_account on customer records that match an account.
// Uses normalizeDistrictName() for fuzzy name matching (same logic as merge).
export function crossLinkCustomers() {
  // Build a lookup of normalized customer names → customer records
  const custByNorm = new Map();
  S._custByName = new Map();
  S.CUSTOMER_DATA.forEach(c => {
    const norm = normalizeDistrictName(c.name);
    // If multiple customers share the same normalized name, keep the first
    if (!custByNorm.has(norm)) custByNorm.set(norm, c);
    S._custByName.set(c.name, c);
  });

  // Build a lookup of normalized account names for the reverse link
  const acctNorms = new Set();
  S.ACCOUNT_DATA.forEach(d => acctNorms.add(normalizeDistrictName(d.name)));

  // Build school-to-district map: normalized school name → district name.
  // Used to set parent_district on customer records for school-level customers.
  const schoolToDistrict = new Map();
  S.ACCOUNT_DATA.forEach(d => {
    if (d._schools && d._schools.length > 0) {
      d._schools.forEach(schoolName => {
        const norm = normalizeDistrictName(schoolName);
        if (!schoolToDistrict.has(norm)) {
          schoolToDistrict.set(norm, d.name);
        }
      });
    }
  });

  // Forward link: account → customer
  let linked = 0;
  S.ACCOUNT_DATA.forEach(d => {
    const norm = normalizeDistrictName(d.name);
    const match = custByNorm.get(norm);
    if (match) {
      d.is_customer = true;
      d.customer_name = match.name;
      linked++;
    } else {
      d.is_customer = false;
      d.customer_name = '';
    }
  });

  // Reverse link: customer → account
  // Also set parent_district for school-level customers
  let parentLinked = 0;
  S.CUSTOMER_DATA.forEach(c => {
    const norm = normalizeDistrictName(c.name);
    c.also_account = acctNorms.has(norm);

    // If customer name matches a school within a district, set parent_district
    const parentDistrict = schoolToDistrict.get(norm);
    if (parentDistrict) {
      c.parent_district = parentDistrict;
      parentLinked++;
    }
  });

  // Count how many customers share the same parent_account (sibling count)
  // and determine if the parent district is itself a customer
  const acctByName = new Map();
  S.ACCOUNT_DATA.forEach(d => acctByName.set(d.name, d));

  const siblingCounts = new Map(); // parent_district → count of customers with that parent
  S.CUSTOMER_DATA.forEach(c => {
    if (c.parent_district) {
      siblingCounts.set(c.parent_district, (siblingCounts.get(c.parent_district) || 0) + 1);
    }
  });

  S.CUSTOMER_DATA.forEach(c => {
    if (c.parent_district) {
      c.sibling_customer_count = siblingCounts.get(c.parent_district) || 0;
      const parentAcct = acctByName.get(c.parent_district);
      c.district_is_customer = parentAcct ? !!parentAcct.is_customer : false;
      // Flag expansion opportunity: only school from this district in our customer base,
      // district is NOT a customer, and district exists in S.ACCOUNT_DATA
      c.expand_opp = c.sibling_customer_count === 1
        && !c.district_is_customer
        && !!parentAcct;
    } else {
      c.sibling_customer_count = 0;
      c.district_is_customer = false;
      c.expand_opp = false;
    }
  });

  if (linked) console.log(`[CrossLink] ${linked} account(s) matched to customer records`);
  if (parentLinked) console.log(`[CrossLink] ${parentLinked} customer(s) linked to parent district`);
}

// ============ JOIN OPPS INTO ACCOUNTS ============
// Merges bundled opps.json data into S.ACCOUNT_DATA at startup.
// Only runs when loading from bundled JSON (not localStorage, which already has opps embedded).
export function joinOppsToAccounts(accounts, opps) {
  const acctByKey = new Map();
  accounts.forEach(d => {
    const key = (d.name || '').toLowerCase().trim() + '|' + (d.state || '').toUpperCase().trim();
    acctByKey.set(key, d);
    const normKey = normalizeDistrictName(d.name) + '|' + (d.state || '').toUpperCase().trim();
    if (!acctByKey.has(normKey)) acctByKey.set(normKey, d);
  });

  const orphans = [];
  opps.forEach(opp => {
    const key = (opp.account_name || '').toLowerCase().trim() + '|' + (opp.state || '').toUpperCase().trim();
    const normKey = normalizeDistrictName(opp.account_name) + '|' + (opp.state || '').toUpperCase().trim();
    const acct = acctByKey.get(key) || acctByKey.get(normKey);
    if (acct) {
      acct.opp_owner = opp.opp_owner || '';
      acct.opportunity_name = opp.opportunity_name || '';
      acct.intro_meeting_date = opp.intro_meeting_date || '';
      acct.created_date = opp.created_date || '';
      acct.last_modified = opp.last_modified || '';
      acct.age = opp.age || '';
      acct._hasUploadedOpp = opp._hasUploadedOpp || false;
      if (opp.metric_improvement_goal) acct.metric_improvement_goal = opp.metric_improvement_goal;
      if (opp.decision_criteria) acct.decision_criteria = opp.decision_criteria;
      if (opp.decision_process) acct.decision_process = opp.decision_process;
      if (opp.paper_process) acct.paper_process = opp.paper_process;
      if (opp.implication_of_pain) acct.implication_of_pain = opp.implication_of_pain;
      acct.opps = opp.opps || [];
      deriveOppSummary(acct);
    } else {
      orphans.push(opp.account_name);
    }
  });

  accounts.forEach(d => {
    if (!d.opps) d.opps = [];
    if (!d.opp_count) deriveOppSummary(d);
  });

  if (orphans.length > 0) {
    console.warn('[Opps Join] Orphaned opps (no matching account):', orphans);
  }
  console.log(`[Opps Join] Joined ${opps.length - orphans.length} opp records into accounts`);
}

// ============ PERFORMANCE INDICES ============
// Pre-computed lookup structures rebuilt when data changes.
// Converts O(n) scans into O(1) lookups for team/rep filtering.
// Performance indices are stored on S (initialized in state.js)

// Look up which team a rep belongs to. Returns team name or null.
export function getTeamForRep(rep) {
  if (!rep) return null;
  return S._repToTeam[rep] || null;
}

export function buildIndices() {
  // Map reps to teams (Set-based for O(1) lookup)
  S._repToTeam = {};
  S._teamRepsSet = {};
  Object.entries(TEAM_REP_DATA).forEach(([team, info]) => {
    const reps = new Set(info.reps);
    if (info.manager) reps.add(info.manager);
    S._teamRepsSet[team] = reps;
    reps.forEach(rep => { S._repToTeam[rep] = team; });
  });

  // Index accounts by rep and team
  S._repToAccounts = {};
  S._teamToAccounts = {};
  S.ACCOUNT_DATA.forEach((d, i) => {
    const tAE = getTerritoryAE(d);
    const hAE = getHoldoutAE(d);
    const managerHeld = isManagerHeld(d);

    // Manager-held accounts are NOT indexed under the manager's name —
    // they are "unassigned" placeholders and belong to the team, not the manager.
    if (!managerHeld) {
      // Index by territory AE
      if (tAE) {
        if (!S._repToAccounts[tAE]) S._repToAccounts[tAE] = [];
        S._repToAccounts[tAE].push(i);
      }
      // Index by holdout AE (if different)
      if (hAE && hAE !== tAE) {
        if (!S._repToAccounts[hAE]) S._repToAccounts[hAE] = [];
        S._repToAccounts[hAE].push(i);
      }
    }
    // Index by team — include manager-held accounts so they appear in team-level views
    // Use direct S._repToTeam lookup (O(1)) instead of iterating all teams (O(teams))
    if (managerHeld) {
      const team = S._repToTeam[d.ae];
      if (team) {
        if (!S._teamToAccounts[team]) S._teamToAccounts[team] = [];
        S._teamToAccounts[team].push(i);
      }
    } else {
      const teams = new Set();
      if (tAE && S._repToTeam[tAE]) teams.add(S._repToTeam[tAE]);
      if (hAE && S._repToTeam[hAE]) teams.add(S._repToTeam[hAE]);
      teams.forEach(team => {
        if (!S._teamToAccounts[team]) S._teamToAccounts[team] = [];
        S._teamToAccounts[team].push(i);
      });
    }

    // Compute _source_team for every account — used to scope "Unassigned Accounts"
    // to the correct team. Manager-held accounts use the manager's team directly.
    // Otherwise checks CSV merge tag, then territory/holdout AE, then opp_owner.
    if (managerHeld) {
      d._source_team = getTeamForRep(d.ae);
    } else if (!d._source_team) {
      d._source_team = getTeamForRep(tAE)
        || getTeamForRep(hAE)
        || getTeamForRep(d.opp_owner)
        || null;
    }
  });

  // De-duplicate team indices (an account may be added for both territory and holdout AE)
  Object.keys(S._teamToAccounts).forEach(team => {
    S._teamToAccounts[team] = [...new Set(S._teamToAccounts[team])];
  });

  // Cache overlap count
  S._overlapCount = S.ACCOUNT_DATA.filter(d => d.is_customer).length;

  // Invalidate caches
  S._uniqueCache = {};
  S._autocompleteCache = null;
}

function invalidateCaches() {
  S._uniqueCache = {};
  S._autocompleteCache = null;
}

// Pre-build autocomplete state/region counts (called lazily on first search)
function getAutocompleteCache() {
  if (S._autocompleteCache) return S._autocompleteCache;

  const stateCounts = {};
  const regionSet = new Set();
  const regionCounts = {};

  S.ACCOUNT_DATA.forEach(d => {
    if (d.state) stateCounts[d.state.toLowerCase()] = (stateCounts[d.state.toLowerCase()] || 0) + 1;
    if (d.region) { regionSet.add(d.region); regionCounts[d.region] = (regionCounts[d.region] || 0) + 1; }
  });
  S.CUSTOMER_DATA.forEach(d => {
    if (d.state) stateCounts[d.state.toLowerCase()] = (stateCounts[d.state.toLowerCase()] || 0) + 1;
    if (d.region) { regionSet.add(d.region); regionCounts[d.region] = (regionCounts[d.region] || 0) + 1; }
  });

  S._autocompleteCache = { stateCounts, regionSet: [...regionSet].sort(), regionCounts };
  return S._autocompleteCache;
}

// ============ TEAM / REP DATA ============
// Built from per-team JSON configs in src/data/teams/.
// To move a rep (e.g. Aric from West to East), edit only the two team JSON files.
const TEAM_CONFIGS = [strategicTeam, entWestTeam, entEastTeam, smbTeam];
export const TEAM_REP_DATA = {};
TEAM_CONFIGS.forEach(cfg => {
  TEAM_REP_DATA[cfg.team] = {
    manager: cfg.manager || null,
    reps: [...cfg.reps],
  };
});

// ============ ACCOUNT ASSIGNMENT RULES ============
// Rule 1: Districts with 30,000+ students → Strategic (Sean Johnson territory), holdout = actual AE
// Rule 2: Districts with <30,000 students → assigned to account owner from data
export const ACCOUNT_PRIMARY_AE = 'Sean Johnson';
export const STRATEGIC_ENROLLMENT_THRESHOLD = 30000;

// Build holdout AEs dynamically from all non-Strategic teams
const ACCOUNT_HOLDOUT_AES = new Set();
Object.entries(TEAM_REP_DATA).forEach(([team, info]) => {
  if (team === 'Strategic') return;
  info.reps.forEach(rep => ACCOUNT_HOLDOUT_AES.add(rep));
  if (info.manager) ACCOUNT_HOLDOUT_AES.add(info.manager);
});

// All active sales reps across every team (including Strategic + managers).
// Used by resolveOwner() to distinguish current reps from former/non-sales staff.
export const ALL_ACTIVE_REPS = new Set();
Object.values(TEAM_REP_DATA).forEach(info => {
  info.reps.forEach(rep => ALL_ACTIVE_REPS.add(rep));
  if (info.manager) ALL_ACTIVE_REPS.add(info.manager);
});

// Managers — derived from team configs for display purposes (e.g. "(Manager)"
// suffix in the rep dropdown). Managers ARE account holders and can own accounts
// just like reps. They are already in ALL_ACTIVE_REPS.
const MANAGERS = new Set();
Object.values(TEAM_REP_DATA).forEach(info => {
  if (info.manager) MANAGERS.add(info.manager);
});

// Returns true if the account is held by a manager (placeholder until assigned to a rep).
// Manager-held accounts are treated as "unassigned" for filtering/display purposes.
export function isManagerHeld(d) {
  if (!d || !d.ae) return false;
  return MANAGERS.has(d.ae);
}

// Former reps (no longer with the company) and employees who left sales.
// Treat identically for territory assignment: their accounts are unassigned
// and fall back to the existing owner or remain ownerless.
const INACTIVE_OWNERS = new Set([
  // Former reps
  'John Tyrrell', 'Zac Otwell', 'Brittany Garrison', 'Bill Lloyd',
  'Jacqueline Layreau', 'Marixza Acuna', 'Sydney Levenfeld', 'Jose Puyol',
  // Still with company but no longer in sales
  'Bella Duffey', 'Scott Walters',
]);

// Ben Foley: still with company, NOT an account holder.
// Accounts with >30k students → hard override to Sean Johnson (no holdout).
// Accounts with ≤30k students or missing enrollment → treat as inactive (holdout logic).
const BEN_FOLEY = 'Ben Foley';

// CTO and SFDC Admin — not account holders.
// Only reassign their accounts when the uploaded CSV contains opp data for the account.
// If opp exists → treat as inactive (run holdout/territory logic).
// If no opp → leave ownership as-is (do not reassign).
const CONDITIONAL_REASSIGN = new Set([
  'Iain Proctor',     // CTO
  'Nicholas Watson',  // SFDC Admin
]);

function getAccountReps() {
  if (!S._accountRepsCache) {
    S._accountRepsCache = getAllRepsForTeam('Strategic');
  }
  return S._accountRepsCache;
}

// Helper: detect NYC Public Schools and sub-districts/schools within NYC.
// NYC is unique: the mega-district (1M+ students) is subdivided into geographic
// districts (e.g. "New York City Geographic District #16") which contain individual
// schools. These accounts use holdout logic (opp owner) instead of a hard territory
// override, so that uploaded opps remain assigned to the opp owner.
function isNYCAccount(name) {
  if (!name) return false;
  const n = name.toLowerCase();
  return n.includes('new york city public schools') || n.includes('nyc public schools')
    || n.includes('new york city geographic district')
    || n.startsWith('nyc ');
}

// Helper: robustly parse enrollment (handles comma-formatted strings like "30,210")
function parseEnrollment(val) {
  if (typeof val === 'number') return val;
  if (!val) return 0;
  return parseInt(String(val).replace(/,/g, '')) || 0;
}

// Helper: returns true if an opp's forecast starts with "Closed" (case-insensitive).
// This is the reliable closed indicator — NOT the stage field.
function isOppClosed(opp) {
  if (!opp) return false;
  const forecast = (opp.forecast || '').trim().toLowerCase();
  return forecast.startsWith('closed');
}

// Helper: inverse of isOppClosed for readability.
function isOppOpen(opp) {
  if (!opp) return false;
  return !isOppClosed(opp);
}

// Helper: returns true if account d has at least one OPEN opp attributable to repName.
// opp_owner is stored at the account level (d.opp_owner), not per-opp.
// If opp_owner matches repName, checks whether any opp on the account is still open.
// If opp_owner is not set, falls back to checking if ANY opp is open (can't distinguish per-rep).
function hasOpenOppByRep(d, repName) {
  const opps = d.opps || [];
  if (opps.length === 0) return false;
  const oppOwner = (d.opp_owner || '').trim();
  // If opp_owner is set and doesn't match the rep, they have no opps here
  if (oppOwner && oppOwner !== repName) return false;
  // Check if at least one opp is still open
  return opps.some(isOppOpen);
}

// Helper: returns the territory (assigned) AE for an account.
// 30k+ enrollment → Strategic (Sean Johnson). <30k → account owner.
export function getTerritoryAE(d) {
  if (isDOE(d.name)) return null;
  // Check strategic enrollment BEFORE bailing on empty ae —
  // unassigned 30k+ accounts still belong to Sean Johnson.
  const enrollment = parseEnrollment(d.enrollment);
  if (enrollment >= STRATEGIC_ENROLLMENT_THRESHOLD) {
    return ACCOUNT_PRIMARY_AE; // strategic account
  }
  // If the account fell through to Opp Owner because the territory rep's data
  // isn't loaded yet, territory_ae holds the original Account Owner from the CSV.
  if (d.territory_ae) return d.territory_ae;
  if (!d.ae) return d.ae;
  return d.ae; // <30k — assigned to account owner
}

// Helper: returns the holdout AE when there's a dual-assignment scenario.
// Two cases: (1) 30k+ strategic account whose AE is not the default (Sean Johnson),
// (2) Opp Owner fallback — territory rep's data isn't loaded yet, so the account is
//     temporarily under the Opp Owner while the territory rep remains the assigned owner.
export function getHoldoutAE(d) {
  if (!d.ae || isDOE(d.name)) return null;
  // Case 2: territory_ae set (Opp Owner fallback) — d.ae is the holdout (Opp Owner)
  if (d.territory_ae && d.territory_ae !== d.ae) {
    // Only show holdout while the holdout rep has at least one OPEN opp
    if (!hasOpenOppByRep(d, d.ae)) return null;
    return d.ae;
  }
  // Case 1: strategic account holdout
  const enrollment = parseEnrollment(d.enrollment);
  if (enrollment >= STRATEGIC_ENROLLMENT_THRESHOLD && d.ae !== ACCOUNT_PRIMARY_AE) {
    // Only show holdout while the holdout rep has at least one OPEN opp
    if (!hasOpenOppByRep(d, d.ae)) return null;
    return d.ae;
  }
  return null;
}

// Resolve the account owner from a CSV value against an existing owner.
// Optional ctx: { enrollment, hasUploadedOpp, oppOwner, loadedReps, accountName } for conditional reassignment.
// Evaluation order (Opp Owner used as fallback when Account Owner is invalid):
//   1. Blank CSV → Opp Owner if active → existing if active → unassigned
//   2. Ben Foley → enrollment > 30k → Sean Johnson; else → Opp Owner / existing / unassigned
//   3. CONDITIONAL_REASSIGN (Iain/Nicholas) → has opp → Opp Owner / existing / unassigned;
//      no opp → keep existing if active, else leave as-is
//   4. INACTIVE_OWNERS → Opp Owner if active → existing if active → unassigned
//   5. (Removed — managers now hold accounts like reps; they flow to step 6)
//   6. Active rep WITH data loaded → assign (unless existing differs → conflict, keep existing)
//      Active rep WITHOUT data loaded → Opp Owner fallback (until their data is uploaded)
//   7. Unrecognized → Opp Owner if active → existing if active → unassigned
// Returns { ae, reason } where ae is the resolved string and reason describes the resolution path.
export function resolveOwner(csvAE, existingAE, ctx) {
  const csv = (csvAE || '').trim();
  const existing = (existingAE || '').trim();
  const oppOwner = (ctx && ctx.oppOwner || '').trim();
  const loadedReps = ctx && ctx.loadedReps;

  // Fallback chain: Opp Owner → existing active rep → unassigned
  const fallback = () => {
    if (oppOwner && ALL_ACTIVE_REPS.has(oppOwner)) return oppOwner;
    return (existing && ALL_ACTIVE_REPS.has(existing)) ? existing : '';
  };

  // 1. CSV AE is blank → fallback (Opp Owner → existing → unassigned)
  if (!csv) {
    return { ae: fallback(), reason: 'blank_owner' };
  }

  // 2. Ben Foley: >30k students → hard override to Sean Johnson (no holdout).
  //    NYC Public Schools exception: use holdout logic (Opp Owner) instead of hard override,
  //    so uploaded opps stay with the opp owner rather than being reassigned to territory.
  //    ≤30k or missing enrollment → fallback (Opp Owner → existing → unassigned).
  if (csv === BEN_FOLEY) {
    const enrollment = ctx ? parseEnrollment(ctx.enrollment) : 0;
    const accountName = ctx && ctx.accountName || '';
    if (enrollment > STRATEGIC_ENROLLMENT_THRESHOLD) {
      // NYC accounts: apply holdout logic — opp owner keeps the account, Sean Johnson is territory
      if (isNYCAccount(accountName)) {
        return { ae: fallback(), reason: 'ben_foley_nyc_holdout' };
      }
      return { ae: ACCOUNT_PRIMARY_AE, reason: 'ben_foley_strategic' }; // Sean Johnson — direct assignment
    }
    return { ae: fallback(), reason: 'ben_foley_fallback' };
  }

  // 3. CONDITIONAL_REASSIGN (Iain Proctor / Nicholas Watson):
  //    Only reassign when the uploaded CSV has opp data for this account.
  //    Has opp → fallback (Opp Owner → existing → unassigned). No opp → leave as-is.
  if (CONDITIONAL_REASSIGN.has(csv)) {
    if (ctx && ctx.hasUploadedOpp) {
      return { ae: fallback(), reason: 'conditional_reassign' };
    }
    // No opp → leave the record as-is, don't overwrite a valid rep
    return { ae: (existing && ALL_ACTIVE_REPS.has(existing)) ? existing : csv, reason: 'conditional_no_opp' };
  }

  // 4. CSV AE is a known inactive/former owner → fallback (Opp Owner → existing → unassigned)
  if (INACTIVE_OWNERS.has(csv)) {
    return { ae: fallback(), reason: 'inactive_owner' };
  }

  // 5. (Removed — managers now hold accounts; they are in ALL_ACTIVE_REPS
  //    and fall through to step 6 like any active rep.)

  // 6. CSV AE is a current, active rep (includes managers)
  if (ALL_ACTIVE_REPS.has(csv)) {
    // Active rep but no data loaded yet → fall through to Opp Owner.
    // When this rep's data is uploaded later, holdout/conflict logic will reconcile.
    if (loadedReps && !loadedReps.has(csv)) {
      return { ae: fallback(), reason: 'no_data_loaded' };
    }
    // If existing is also a different active rep (and not the Strategic primary default)
    // → conflict: keep existing owner, conflict is logged separately in the merge
    if (existing && ALL_ACTIVE_REPS.has(existing) && existing !== csv && existing !== ACCOUNT_PRIMARY_AE) {
      return { ae: existing, reason: 'conflict_kept_existing' };
    }
    // Otherwise assign the CSV rep (new account, same rep, or existing was the Strategic default)
    return { ae: csv, reason: 'direct_assign' };
  }

  // 7. CSV AE is an unrecognized name (not active, not in inactive list, not a manager)
  // → fallback (Opp Owner → existing → unassigned)
  return { ae: fallback(), reason: 'unrecognized' };
}

// ============ STATE ============
// All state variables are stored on S (see state.js). Accessed via S.xxx throughout.
const MULTI_SELECT_FILTERS = new Set(['strat_state', 'strat_sis', 'cust_state']);

// ============ STATE SYNC ============

function computeStratIconClass(d) {
  const students = parseInt(d.enrollment) || 0;
  const isLarge = students > 50000;
  let oppClass = '';
  if (d.opp_stage) {
    if (d.opp_stage.startsWith('1')) oppClass = ' opp-discovery';
    else if (d.opp_stage.startsWith('2')) oppClass = ' opp-demo';
    else if (d.opp_stage.startsWith('3')) oppClass = ' opp-scoping';
    else if (d.opp_stage.startsWith('4')) oppClass = ' opp-proposal';
    else if (d.opp_stage.startsWith('5')) oppClass = ' opp-validation';
    else if (d.opp_stage.startsWith('6')) oppClass = ' opp-procurement';
    else oppClass = ' has-opp';
  }
  const noteKey = 'edia_notes_' + d.name.replace(/[^a-zA-Z0-9]/g, '_');
  const hasNote = S._accountsWithNotes.has(noteKey) ? ' has-note' : '';
  const isCust = d.is_customer ? ' is-customer' : '';
  const doeClass = isDOE(d.name) ? ' is-doe' : '';
  return `marker-strat${oppClass}${hasNote}${isCust}${doeClass} ${isLarge ? 'large' : ''}`;
}

function computeCustIconClass(d) {
  const isAlsoAcct = d.also_account ? ' also-account' : '';
  const expandOpp = d.expand_opp ? ' expand-opp' : '';
  return `marker-cust${isAlsoAcct}${expandOpp}`;
}

function getIconSize(d, type) {
  if (type === 'customer') {
    return d.also_account ? [14, 14] : [10, 10];
  }
  const students = parseInt(d.enrollment) || 0;
  return students > 50000 ? [18, 18] : [14, 14];
}

function getIconAnchor(d, type) {
  if (type === 'customer') {
    return d.also_account ? [7, 7] : [5, 5];
  }
  const students = parseInt(d.enrollment) || 0;
  return students > 50000 ? [9, 9] : [7, 7];
}

/** Build the marker pool from all accounts and customers. Called once after data load. */
function buildMarkerPool() {
  S._markerPool = new Map();
  S.ACCOUNT_DATA.forEach(d => {
    if (!d.lat || !d.lng) return;
    const mlKey = d.name + '|' + (d.state || '');
    const cls = computeStratIconClass(d);
    const icon = L.divIcon({
      className: cls,
      iconSize: getIconSize(d, 'accounts'),
      iconAnchor: getIconAnchor(d, 'accounts'),
    });
    const marker = L.marker([d.lat, d.lng], { icon });
    marker.on('click', function() {
      ensurePopup(marker, d, 'accounts');
      S.map.once('moveend', function() { marker.openPopup(); });
      S.map.flyTo([d.lat + 2.5, d.lng], 7, { duration: 0.6 });
    });
    S._markerPool.set('a:' + mlKey, { marker, data: d, type: 'accounts', currentClass: cls });
  });
  S.CUSTOMER_DATA.forEach(d => {
    if (!d.lat || !d.lng) return;
    const mlKey = d.name + '|' + (d.state || '');
    const cls = computeCustIconClass(d);
    const icon = L.divIcon({
      className: cls,
      iconSize: getIconSize(d, 'customer'),
      iconAnchor: getIconAnchor(d, 'customer'),
    });
    const marker = L.marker([d.lat, d.lng], { icon });
    marker.on('click', function() {
      ensurePopup(marker, d, 'customer');
      S.map.once('moveend', function() { marker.openPopup(); });
      S.map.flyTo([d.lat + 2.5, d.lng], 7, { duration: 0.6 });
    });
    S._markerPool.set('c:' + mlKey, { marker, data: d, type: 'customer', currentClass: cls });
  });
  S._markerPoolBuilt = true;
}

/** Update a single marker's icon class if it has changed. */
function updateMarkerIcon(entry, newClass) {
  if (entry.currentClass !== newClass) {
    const icon = L.divIcon({
      className: newClass,
      iconSize: getIconSize(entry.data, entry.type),
      iconAnchor: getIconAnchor(entry.data, entry.type),
    });
    entry.marker.setIcon(icon);
    entry.currentClass = newClass;
    // Invalidate cached popup since data may have changed
    if (entry.marker.getPopup()) {
      entry.marker.unbindPopup();
    }
  }
}

/** Rebuild the marker pool after data changes (merge, crosslink, etc.) */
function rebuildMarkerPool() {
  // Remove all existing markers from layers
  if (S.stratLayer) S.stratLayer.clearLayers();
  if (S.custLayer) S.custLayer.clearLayers();
  S._markerPoolBuilt = false;
  S._previouslyVisiblePoolKeys = new Set();
  buildMarkerPool();
}

// ============ NOTE INDEX CACHE ============
// Cache which accounts have notes to avoid 7,167 localStorage reads per filter change
function rebuildNoteIndex() {
  S._accountsWithNotes = new Set();
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key && key.startsWith('edia_notes_')) {
      try { if (JSON.parse(localStorage.getItem(key)).length > 0) S._accountsWithNotes.add(key); }
      catch(e) {}
    }
  }
}

